void reverse(int a[], int left, int right) {
    while (left < right) {
        int t = a[left]; a[left] = a[right]; a[right] = t;
        ++left; --right;
    }
}
void rotateLeft(int a[], int n, int p) {
    if (a == NULL || n <= 1) return;
    p %= n;
    if (p < 0) p += n;
    reverse(a, 0, p - 1);
    reverse(a, p, n - 1);
    reverse(a, 0, n - 1);
}

int medianOfTwoSorted(int A[], int B[], int n) {
    int s1 = 0, d1 = n - 1, s2 = 0, d2 = n - 1;
    while (s1 != d1 || s2 != d2) {
        int m1 = (s1 + d1) / 2;
        int m2 = (s2 + d2) / 2;
        if (A[m1] == B[m2]) return A[m1];
        if (A[m1] < B[m2]) {
            if ((d1 - s1 + 1) % 2 == 1) {
                s1 = m1;
                d2 = m2;
            } else {
                s1 = m1 + 1;
                d2 = m2;
            }
        } else {
            if ((d1 - s1 + 1) % 2 == 1) {
                d1 = m1;
                s2 = m2;
            } else {
                d1 = m1;
                s2 = m2 + 1;
            }
        }
    }
    return A[s1] < B[s2] ? A[s1] : B[s2];
}

