typedef struct Node { char data; struct Node *next; } Node;
int length(Node *h) {
    int n = 0;
    for (Node *p = h->next; p != NULL; p = p->next) ++n;
    return n;
}
Node *commonSuffixStart(Node *h1, Node *h2) {
    int m = length(h1), n = length(h2);
    Node *p = h1, *q = h2;
    for (int i = 0; i < m - n; ++i) p = p->next;
    for (int i = 0; i < n - m; ++i) q = q->next;
    while (p != q) {
        p = p->next;
        q = q->next;
    }
    return p; // NULL 表示没有公共后缀
}

int Majority(const int A[], int n) {
    if (A == NULL || n <= 0) return -1;
    int candidate = 0, count = 0;
    for (int i = 0; i < n; ++i) {
        if (count == 0) { candidate = A[i]; count = 1; }
        else if (A[i] == candidate) ++count;
        else --count;
    }
    count = 0;
    for (int i = 0; i < n; ++i)
        if (A[i] == candidate) ++count;
    return count > n / 2 ? candidate : -1;
}

