static int partition(int a[], int low, int high) {
    int pivot = a[low];
    int l = low, r = high;
    while (l < r) {
        while (l < r && a[r] >= pivot) --r;
        if (l < r) a[l++] = a[r];
        while (l < r && a[l] <= pivot) ++l;
        if (l < r) a[r--] = a[l];
    }
    a[l] = pivot;
    return l;
}

long long splitMaxDifference(int a[], int n) {
    int k = n / 2;
    int low = 0, high = n - 1;
    while (low < high) {
        int p = partition(a, low, high);
        if (p == k) break;
        if (p < k) low = p + 1;
        else high = p - 1;
    }
    long long s1 = 0, s2 = 0;
    for (int i = 0; i < k; ++i) s1 += a[i];
    for (int i = k; i < n; ++i) s2 += a[i];
    return s2 - s1;
}
